import {api} from './accounts.mjs';
import {label,ui} from './language.mjs';
import {searchText,pageItems} from './lists.mjs';
import {pagination} from './directory-ui.mjs';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export async function mountAdministration(root,store,{onDelete,onRestore}){
 const [a,t]=await Promise.all([api('admin/accounts',{proof:store.proof}),api('admin/trash',{proof:store.proof})]);if(!root.isConnected)return;
 const typeLabels={mothers:'Maternal profile',children:'Child profile',growth:'Measurement',vaccines:'Vaccination',inventory:'Vaccine batch',guides:'Clinic guide',visits:'Visit'};let query='',accountPage=1,trashPage=1;root.innerHTML=ui`<p class="notice">Delete and restore require an internet connection and a synced clinic copy. Deleted items stay in Trash until restored.</p><div class="toolbar"><label class="search-box" for="admin-search">Search accounts and Trash<input id="admin-search" type="search" placeholder="Search name or username…"></label></div><section class="panel admin-section"><h2>Clinic accounts</h2><div id="admin-accounts"></div></section><section class="panel admin-section"><h2>Trash</h2><p>Restoring a profile does not automatically restore patient links or companion access. Refunded reservations return as cancelled and need staff approval again.</p><div id="admin-trash"></div></section>`;
 function draw(){const accounts=pageItems(a.accounts.filter(x=>searchText(x.displayName+' '+x.username).includes(searchText(query))),accountPage);accountPage=accounts.page;root.querySelector('#admin-accounts').innerHTML=accounts.items.map(x=>ui`<div class="admin-row"><div><strong>${esc(x.displayName)}</strong><small>@${esc(x.username)} · ${label(x.role==='staff'?'Clinic staff':'Patient / guardian')} · ${label(x.active?'Active':'In Trash')}</small></div>${x.current?ui`<span class="badge">Current account</span>`:x.active?ui`<button class="row-button danger-action" data-delete-account="${esc(x.id)}">Delete account</button>`:ui`<span class="badge muted">In Trash</span>`}</div>`).join('')+pagination(accounts,'admin-accounts');const entries=pageItems(t.entries.filter(x=>searchText(x.summary).includes(searchText(query))),trashPage);trashPage=entries.page;root.querySelector('#admin-trash').innerHTML=entries.items.map(x=>ui`<div class="admin-row"><div><strong>${esc(x.summary)}</strong><small>${label(x.kind==='account'?'Account':typeLabels[x.record_type]??'Care record')} · ${new Date(x.deleted_at).toLocaleDateString()}</small></div><button class="row-button" data-restore-trash="${esc(x.id)}">Restore</button></div>`).join('')+(entries.total?'':ui`<p>Trash is empty.</p>`)+pagination(entries,'admin-trash');}
 root.querySelector('#admin-search').oninput=e=>{query=e.target.value;accountPage=trashPage=1;draw();};
 root.onclick=e=>{const deletion=e.target.closest('[data-delete-account]');if(deletion){onDelete(a.accounts.find(x=>x.id===deletion.dataset.deleteAccount));return;}const restore=e.target.closest('[data-restore-trash]');if(restore){onRestore(t.entries.find(x=>x.id===restore.dataset.restoreTrash));return;}const page=e.target.closest('[data-list-page]');if(page){if(page.dataset.listKey==='admin-accounts')accountPage=Number(page.dataset.listPage);else trashPage=Number(page.dataset.listPage);draw();}};draw();
}
